// Adapted from organized-experiment-workspace-overview founder-crm-lite/src/modules/crm/service.ts:83-176 @ 63ed0a7
// (listLeads, getLeadDetail, globalSearch; the JSON-file repository replaced by an injected db).
// The study path's fix for finding 2 is APPLIED: globalSearch leads use listLeads' owner filter
// (CODEBASE-STUDY-PATH.md:829, :870).
const visibleTo = (user) => (record) => (user.role === "sales_rep" ? record.ownerId === user.id : true);

export function listLeads(db, user, filters = {}) {
  const q = filters.q?.trim().toLowerCase();
  return db.leads
    .filter(visibleTo(user))
    .filter((lead) => (filters.status ? lead.status === filters.status : true))
    .filter((lead) => (q ? [lead.fullName, lead.email ?? "", lead.notesSummary].join(" ").toLowerCase().includes(q) : true));
}

export function getLeadDetail(db, user, leadId) {
  const lead = db.leads.find((entry) => entry.id === leadId);
  if (!lead) {
    return null;
  }
  if (user.role === "sales_rep" && lead.ownerId !== user.id) {
    throw new Error("You do not have access to this lead.");
  }
  return { lead };
}

export function globalSearch(db, user, query) {
  const q = query.trim().toLowerCase();
  if (!q) {
    return { leads: [], deals: [] };
  }

  return {
    leads: db.leads
      .filter(visibleTo(user))
      .filter((lead) => [lead.fullName, lead.email ?? "", lead.notesSummary].join(" ").toLowerCase().includes(q)),
    deals: db.deals
      .filter(visibleTo(user))
      .filter((deal) => [deal.name, deal.notesSummary, deal.stage].join(" ").toLowerCase().includes(q))
  };
}
